INSERT INTO "public"."riding_logs_record" ("id", "date", "notes", "created_at", "updated_at", "author_id", "horse_id") VALUES
('1', '2023-08-17', 'Today was Titus\' first time riding in the woods without any other horses or people. He did really well, with the exception of one little spook from a deer. This occurred before we entered the woods, so I took him to the arena to get some of the freshness out of him first. After about 30 mins in the arena he settled down and we proceeded down the trail. We did two water crossings and did not have any problems. It was a great ride', '2024-10-17 17:24:18.534239+00', '2024-10-17 17:24:18.534239+00', '1', '4d8df2dd-17dd-4ab3-8618-8d567b8ced6b'),
